/**
 * G-STATE / G-ACTIONLOG generator (RULE_PROPERTIES §4): seeded random-legal play on a small synthetic lexicon.
 * Moves are generated by brute force (every lexicon form through every anchor) and scored through the engine's
 * own `evaluateMove`, so the harness never re-implements a rule.
 */
import {
  createReferenceIndex,
  type DefinitionHash,
  type LexiconIndex,
  type LexiconVersion,
  type ReferenceTermInput,
} from '@codelex/lexicon/index';
import { evaluateMove, observe } from '../../src/match/observe.js';
import { createRng, deriveStreamState, type Rng } from '../../src/rng/index.js';
import type {
  Action,
  BoardTile,
  EngineContext,
  MatchConfig,
  MatchState,
  MoveEvaluation,
  Placement,
  RackTile,
  SeedHex,
} from '../../src/types.js';
import { chars } from '../../src/tiles.js';

/** Synthetic playtest-like vocabulary: short forms (many two-letter ones) so random racks find moves. */
const FORMS = [
  'AI',
  'AD',
  'CD',
  'IP',
  'OS',
  'IO',
  'ID',
  'IT',
  'UI',
  'DB',
  'PC',
  'QA',
  'AR',
  'VR',
  'UX',
  'GO',
  'CI',
  'OR',
  'IF',
  'KB',
  'MB',
  'GB',
  'TB',
  'ML',
  'NO',
  'ON',
  'TO',
  'AT',
  'AN',
  'IN',
  'AS',
  'BE',
  'RE',
  'DE',
  'ET',
  'ES',
  'API',
  'TCP',
  'UDP',
  'DNS',
  'CDN',
  'SQL',
  'CSS',
  'NET',
  'BIT',
  'BUG',
  'DEV',
  'OPS',
  'LOG',
  'RUN',
  'SET',
  'GET',
  'PUT',
  'TAR',
  'ZIP',
  'KEY',
  'RAM',
  'ROM',
  'CPU',
  'GPU',
  'NAT',
  'ETL',
  'GIT',
  'POD',
  'TEST',
  'NODE',
  'CODE',
  'DATA',
  'BYTE',
  'HASH',
  'JAVA',
  'RUST',
  'LINT',
  'JSON',
  'CLOUD',
  'TOKEN',
  'CACHE',
  'STACK',
  'QUEUE',
  'ROUTE',
  'PROXY',
  'REDIS',
  'LINUX',
  'PYTHON',
  'DOCKER',
  'SERVER',
  'KERNEL',
  'BUCKET',
  'ROUTER',
  'CONTAINER',
  'KUBERNETES',
];
const PLURALS: Readonly<Record<string, string>> = {
  POD: 'PODS',
  BUG: 'BUGS',
  KEY: 'KEYS',
  LOG: 'LOGS',
  NODE: 'NODES',
  TOKEN: 'TOKENS',
  BUCKET: 'BUCKETS',
  SERVER: 'SERVERS',
  ROUTER: 'ROUTERS',
  CONTAINER: 'CONTAINERS',
  TEST: 'TESTS',
  BYTE: 'BYTES',
};
const RELATIONS: readonly (readonly [string, string])[] = [
  ['POD', 'KUBERNETES'],
  ['CONTAINER', 'KUBERNETES'],
  ['DOCKER', 'CONTAINER'],
  ['TCP', 'IP'],
  ['UDP', 'IP'],
  ['DNS', 'IP'],
  ['CDN', 'CLOUD'],
  ['BUCKET', 'CLOUD'],
  ['CACHE', 'REDIS'],
  ['CPU', 'GPU'],
  ['RAM', 'ROM'],
  ['GIT', 'CODE'],
  ['LINT', 'CODE'],
  ['TEST', 'CODE'],
  ['JSON', 'API'],
  ['SERVER', 'CLOUD'],
  ['STACK', 'QUEUE'],
];
/**
 * Every 2- and 3-letter string is playable in this synthetic lexicon, so that single tiles can almost always be
 * placed and matches reach the endgame (empty bag, going out). Only the harness's fallback uses them.
 */
const LETTERS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
const SHORT = LETTERS.flatMap((a) =>
  LETTERS.flatMap((b) => [a + b, ...LETTERS.map((c) => a + b + c)]),
).filter((form) => !FORMS.includes(form) && !Object.values(PLURALS).includes(form));
const DIFFICULTIES = ['novice', 'intermediate', 'advanced', 'expert'] as const;

export const SIM_VERSION = 'abcdefabcdefabcd' as LexiconVersion;
export const SIM_HASH = '0123012301230123' as DefinitionHash;

export function simLexicon(): LexiconIndex {
  const terms: ReferenceTermInput[] = [...FORMS, ...SHORT].map((form, i) => ({
    id: form.toLowerCase(),
    playable: true,
    form,
    difficulty: DIFFICULTIES[i % 4] ?? 'novice',
    categories: ['cloud'],
    inflections: PLURALS[form] === undefined ? [] : [{ form: PLURALS[form] ?? '', kind: 'plural' }],
    relations: RELATIONS.filter(([a]) => a === form).map(([, b]) => ({
      type: 'related_to',
      target: b.toLowerCase(),
    })),
    gameValue: 1,
    knowledgeXp: 1,
  }));
  return createReferenceIndex({
    version: SIM_VERSION,
    profile: { id: 'global-ranked', kind: 'global', definitionHash: SIM_HASH },
    document: { terms },
  });
}

export const SIM_CTX: EngineContext = { lexicon: simLexicon() };
const ALL_FORMS = [...FORMS, ...Object.values(PLURALS)];

export function simConfig(seed: string, seats = 2): MatchConfig {
  const teams =
    seats === 2
      ? [[0], [1]]
      : seats === 4 && seed.endsWith('0')
        ? [
            [0, 2],
            [1, 3],
          ]
        : Array.from({ length: seats }, (_, i) => [i]);
  return {
    seed: seed as SeedHex,
    engineRulesVersion: 1,
    lexiconVersion: SIM_VERSION,
    profileId: 'global-ranked',
    definitionHash: SIM_HASH,
    config: {
      mode: 'classic',
      format: seats === 2 ? 'untimed-vs-bot' : 'untimed',
      seats,
      teams,
      layout: 'classic-v1',
      letters: 'letters-v1',
      requireWinner: seed.endsWith('1') ? 1 : 0,
    },
  };
}

/** A seeded test RNG (not a bot stream: the harness is not a bot). */
export function harnessRng(seed: string): Rng {
  return createRng(deriveStreamState(seed, 'test-harness'));
}

/** Up to `limit` legal PLACE_WORD evaluations for the seat on turn, found in an RNG-chosen anchor order. */
export function legalMoves(state: MatchState, rng: Rng, limit: number): MoveEvaluation[] {
  const seat = state.seatOnTurn;
  const observation = observe(state, seat);
  const board = state.board;
  const empty = board.every((row) => /^\.+$/.test(row));
  const anchors: [number, number][] = [];
  if (empty) anchors.push([7, 7]);
  else {
    for (let r = 0; r < 15; r += 1) {
      for (let c = 0; c < 15; c += 1) if (board[r]?.charAt(c) !== '.') anchors.push([r, c]);
    }
  }
  const order = rng.shuffle(anchors).slice(0, 8);
  const forms = rng.shuffle(ALL_FORMS).slice(0, 40);
  const found: MoveEvaluation[] = [];
  const seen = new Set<string>();
  for (const [ar, ac] of order) {
    for (const vertical of [false, true]) {
      for (const form of forms) {
        for (let i = 0; i < form.length; i += 1) {
          const at = board[ar]?.charAt(ac) ?? '.';
          if (!empty && at.toUpperCase() !== form.charAt(i)) continue;
          const tiles = buildPlacement(board, observation.rack, form, ar, ac, i, vertical);
          if (tiles === undefined) continue;
          const key = JSON.stringify(tiles);
          if (seen.has(key)) continue;
          seen.add(key);
          const r = evaluateMove(observation, { seat, type: 'PLACE_WORD', tiles }, SIM_CTX);
          if (r.ok) {
            found.push(r.value);
            if (found.length >= limit) return found;
          }
        }
      }
    }
  }
  return found;
}

function buildPlacement(
  board: readonly string[],
  rack: string,
  form: string,
  ar: number,
  ac: number,
  index: number,
  vertical: boolean,
): Placement[] | undefined {
  const available = chars(rack);
  const tiles: Placement[] = [];
  for (let k = 0; k < form.length; k += 1) {
    const r = vertical ? ar + k - index : ar;
    const c = vertical ? ac : ac + k - index;
    if (r < 0 || c < 0 || r > 14 || c > 14) return undefined;
    const square = board[r]?.charAt(c) ?? '.';
    const letter = form.charAt(k);
    if (square !== '.') {
      if (square.toUpperCase() !== letter) return undefined;
      continue;
    }
    let pos = available.indexOf(letter);
    let tile: string = letter;
    if (pos === -1) {
      pos = available.indexOf('?');
      tile = letter.toLowerCase();
    }
    if (pos === -1) return undefined;
    available.splice(pos, 1);
    tiles.push({ row: r, col: c, tile: tile as BoardTile });
  }
  return tiles.length > 0 ? tiles : undefined;
}

/** The next action of a random-legal player (sometimes resigns, exchanges or passes). */
export function chooseAction(state: MatchState, rng: Rng): Action {
  const seat = state.seatOnTurn;
  const roll = rng.int(0, 1000);
  if (roll < 3) return { seat, type: 'RESIGN' };
  if (roll < 985) {
    const moves = legalMoves(state, rng, 2);
    if (moves.length > 0) return (moves[rng.int(0, moves.length)] as MoveEvaluation).action;
    const single = singleTileMove(state, rng);
    if (single !== undefined) return single.action;
  }
  const rack = state.seats[seat]?.rack ?? '';
  if (state.bag.length >= 7 && rack.length > 0 && rng.int(0, 2) === 0) {
    const count = rng.int(1, rack.length + 1);
    return {
      seat,
      type: 'EXCHANGE',
      tiles: rng.shuffle(chars(rack)).slice(0, count) as RackTile[],
    };
  }
  return { seat, type: 'PASS' };
}

/** Fallback: one rack tile on an empty square next to the board (first legal one in an RNG order). */
function singleTileMove(state: MatchState, rng: Rng): MoveEvaluation | undefined {
  const seat = state.seatOnTurn;
  const observation = observe(state, seat);
  const board = state.board;
  const occupied = (r: number, c: number): boolean =>
    r >= 0 && c >= 0 && r < 15 && c < 15 && board[r]?.charAt(c) !== '.';
  const squares: [number, number][] = [];
  for (let r = 0; r < 15; r += 1) {
    for (let c = 0; c < 15; c += 1) {
      if (
        !occupied(r, c) &&
        (occupied(r - 1, c) || occupied(r + 1, c) || occupied(r, c - 1) || occupied(r, c + 1))
      ) {
        squares.push([r, c]);
      }
    }
  }
  const rack = chars(observation.rack);
  for (const [row, col] of rng.shuffle(squares).slice(0, 15)) {
    for (const tile of rng.shuffle(rack)) {
      const placed = (tile === '?' ? LETTERS[rng.int(0, 26)]?.toLowerCase() : tile) as BoardTile;
      const r = evaluateMove(
        observation,
        { seat, type: 'PLACE_WORD', tiles: [{ row, col, tile: placed }] },
        SIM_CTX,
      );
      if (r.ok) return r.value;
    }
  }
  return undefined;
}
